{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Edaravone, a 1-phenyl-3-methyl-pyrazolin-5-one closely related to the query pyrazolone, has an absolute oral bioavailability of 57.3% in healthy Japanese subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Pirfenidone, a 1-phenyl-5-methylpyridin-2-one sharing the phenyl-methyl heterocycle, is rapidly absorbed with high oral bioavailability in humans and nonclinical species, supporting a high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Clobazam, an N-methyl/N-phenyl heterocyclic lactam, has absolute oral bioavailability of 90–100% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Roquinimex, which contains the N-methyl-N-phenyl amide/lactam motif, shows complete oral bioavailability in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Meperidine, a small N-methyl phenyl-containing drug with substantial first-pass metabolism, still has absolute oral bioavailability of ~52%, indicating that first-pass liability does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rutaecarpine, a fused polycyclic alkaloid, has low oral bioavailability in animals and humans; however, its low similarity and poor solubility phenotype limit transfer to the small, soluble pyrazolone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, lipophilic pyrazolone (aminopyrine-like) with favorable physicochemical properties. The closest analogue, edaravone, has absolute oral bioavailability ~57% in humans, and numerous structurally related N-methyl/N-phenyl heterocycles show F ≥ 50%. Only the dissimilar fused alkaloid rutaecarpine is low, with poor transferability. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for aminopyrine itself is provided.",
    "First-pass metabolism of the dimethylamino group is not directly quantified.",
    "One edaravone oral suspension record reports poor bioavailability, conflicting with absolute F ~57% measurements; formulation-specific effects are unresolved.",
    "Morgan similarities are modest, so transferability from individual analogues is limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

